using System; using System.Linq; using Mono.Cecil; class A { static int Main(string[] a) { var asm = AssemblyDefinition.ReadAssembly(a[0]); foreach (var f in a.Skip(1)) { foreach (var t in asm.MainModule.Types.Where(x => x.Name == f)) { Console.WriteLine("== " + t.FullName + " =="); foreach (var m in t.Methods) Console.WriteLine("  M " + m.Name + " pub=" + m.IsPublic + " priv=" + m.IsPrivate + " fam=" + m.IsFamily + " asm=" + m.IsAssembly + " famasm=" + m.IsFamilyOrAssembly + " static=" + m.IsStatic); foreach (var fd in t.Fields) Console.WriteLine("  F " + fd.Name + " pub=" + fd.IsPublic + " priv=" + fd.IsPrivate + " fam=" + fd.IsFamily + " asm=" + fd.IsAssembly); } } return 0; } }
